14:   Future<List<CurrencyModel>> getCurrencyList() async {
15:     final String? response = await _httpClient.getDecodedResponse(RestPath.dailyExchangeRateUrl);
16:     if (response == null) return const <CurrencyModel>[];
17: 
18:     final Map<String, dynamic> json = jsonDecode(response);
19: 
20:     return CurrencyListResponseDto.fromJson(json).valute.values.map((e) => e.model).toList(growable: false);
21:   }
22: 
23:   @override
24:   Future<List<NewsModel>> getNewsList() async {
25:     final String? response = await _httpClient.getDecodedResponse(RestPath.newsUrl);
26:     if (response == null) return const <NewsModel>[];
27: 
28:     return RssFeed.parse(response).items.map((e) => e.asNewsModel).toList(growable: false);
29:   }
30: }

